mapper.select:
select gc.shop_id,gc.shop_name from goods_dealer_putaway_record gdpr left join ${database.prefix.goods}hou_goods_common gc on gdpr.dealer_common_id = gc.common_id where gc.common_name is not null and gdpr.supply_common_id = #{param.supplyCommonId}
and gc.shop_name like CONCAT('%',#{param.shopName},'%')
group by gc.shop_id
